So, you need to change the onTrigger function to return a new function that updates the state. Here's how you can do it:

const EnhancedButton = withStateHandlers(
  ({ initialState = false }) => ({ active: initialState }),
  {
    onTrigger: (state, props) => (newState => ({ active: true }))
  }
)(({ active, onTrigger, children, id }) => {
  console.log(active)
  return (
    <Button
      onClick={() => onTrigger()(active)}
      toggle
      active={active}
      size="massive"
      style={styles.button}
      as={Link}
      to={`/${id}`}
    >
      {children}
    </Button>
  )
})

Now, when you click the button, it will call onTrigger with the current active state, which will update the state to active: true. When you navigate away and come back, the button will still be active: true.

